/**
 * Headless Tetris core.
 *
 * Well: 10 wide x 20 tall. Row 0 is the TOP, row 19 the BOTTOM; col 0 is left.
 *
 * Rotation: simple, nudge-free clockwise rotation of the piece's bounding
 * matrix (width/height swap). NO wall kicks / floor kicks of any kind. If a
 * rotated orientation would overlap the stack or leave the well, the rotation
 * is rejected and the piece keeps its current orientation. The same rule
 * guards `left`/`right`/gravity: every mutation is only applied when the
 * resulting position is fully inside the well and collision-free, so a piece
 * can never overlap the stack or stick out of the well by construction.
 *
 * Scoring: 100 points per cleared line.
 */

export const WIDTH = 10;
export const HEIGHT = 20;
export const POINTS_PER_LINE = 100;

export type PieceType = 'I' | 'O' | 'T' | 'S' | 'Z' | 'J' | 'L';
export type Command = 'left' | 'right' | 'rotate' | 'hardDrop';

/** Spawn orientations. J/L distinguished by where the nub sits on the bar row. */
export const SHAPES: Record<PieceType, number[][]> = {
  I: [[1, 1, 1, 1]],
  O: [
    [1, 1],
    [1, 1],
  ],
  T: [
    [1, 1, 1],
    [0, 1, 0],
  ],
  S: [
    [0, 1, 1],
    [1, 1, 0],
  ],
  Z: [
    [1, 1, 0],
    [0, 1, 1],
  ],
  J: [
    [1, 0, 0],
    [1, 1, 1],
  ], // nub upper-LEFT
  L: [
    [0, 0, 1],
    [1, 1, 1],
  ], // nub upper-RIGHT
};

export interface ActivePiece {
  type: PieceType;
  mat: number[][];
  x: number; // col of top-left corner of bounding box
  y: number; // row of top-left corner of bounding box
}

export interface GameState {
  grid: number[][]; // HEIGHT x WIDTH of 0/1, locked cells only
  queue: PieceType[];
  nextIndex: number;
  active: ActivePiece | null;
  linesCleared: number;
  score: number;
  gameOver: boolean;
}

/** Clockwise rotation via width/height swap of the bounding matrix. */
export function rotateCW(mat: number[][]): number[][] {
  const rows = mat.length;
  const cols = mat[0].length;
  const out: number[][] = Array.from({ length: cols }, () => Array(rows).fill(0));
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++) out[c][rows - 1 - r] = mat[r][c];
  return out;
}

function collides(grid: number[][], mat: number[][], x: number, y: number): boolean {
  for (let r = 0; r < mat.length; r++)
    for (let c = 0; c < mat[0].length; c++) {
      if (!mat[r][c]) continue;
      const gx = x + c;
      const gy = y + r;
      if (gx < 0 || gx >= WIDTH || gy < 0 || gy >= HEIGHT) return true; // outside well
      if (grid[gy][gx]) return true; // overlaps locked stack
    }
  return false;
}

function spawnNext(state: GameState): void {
  if (state.nextIndex >= state.queue.length) {
    state.gameOver = true;
    state.active = null;
    return;
  }
  const type = state.queue[state.nextIndex++];
  const mat = SHAPES[type].map((row) => [...row]);
  const x = Math.floor((WIDTH - mat[0].length) / 2); // centered horizontally
  const y = 0; // top row
  const active: ActivePiece = { type, mat, x, y };
  if (collides(state.grid, mat, x, y)) {
    state.active = active;
    state.gameOver = true; // blocked spawn
    return;
  }
  state.active = active;
}

export function createGame(queue: PieceType[]): GameState {
  const state: GameState = {
    grid: Array.from({ length: HEIGHT }, () => Array(WIDTH).fill(0)),
    queue: [...queue],
    nextIndex: 0,
    active: null,
    linesCleared: 0,
    score: 0,
    gameOver: false,
  };
  spawnNext(state);
  return state;
}

function lockPiece(state: GameState): void {
  const p = state.active!;
  for (let r = 0; r < p.mat.length; r++)
    for (let c = 0; c < p.mat[0].length; c++)
      if (p.mat[r][c]) state.grid[p.y + r][p.x + c] = 1;

  // Clear full rows, shift everything above down.
  let cleared = 0;
  for (let r = HEIGHT - 1; r >= 0; r--) {
    if (state.grid[r].every((cell) => cell === 1)) {
      state.grid.splice(r, 1);
      state.grid.unshift(Array(WIDTH).fill(0));
      cleared++;
      r++; // re-check same index after shift
    }
  }
  state.linesCleared += cleared;
  state.score += cleared * POINTS_PER_LINE;
  spawnNext(state);
}

/** Apply one command. All moves are checked first: invalid ones are no-ops. */
export function step(state: GameState, cmd: Command): GameState {
  if (state.gameOver || !state.active) return state;
  const p = state.active;
  switch (cmd) {
    case 'left':
      if (!collides(state.grid, p.mat, p.x - 1, p.y)) p.x -= 1;
      break;
    case 'right':
      if (!collides(state.grid, p.mat, p.x + 1, p.y)) p.x += 1;
      break;
    case 'rotate': {
      // Nudge-free: try in place, reject entirely if it doesn't fit.
      const rotated = rotateCW(p.mat);
      if (!collides(state.grid, rotated, p.x, p.y)) p.mat = rotated;
      break;
    }
    case 'hardDrop':
      while (!collides(state.grid, p.mat, p.x, p.y + 1)) p.y += 1;
      lockPiece(state);
      break;
  }
  return state;
}

/** Run a command sequence, returning snapshots of the state after each step. */
export function run(queue: PieceType[], commands: Command[]): { final: GameState; history: GameState[] } {
  const state = createGame(queue);
  const history: GameState[] = [];
  for (const cmd of commands) {
    step(state, cmd);
    history.push(JSON.parse(JSON.stringify(state)));
  }
  return { final: state, history };
}

/** ASCII of the LOCKED grid only ('#' filled, '.' empty), top row first. */
export function renderGrid(state: GameState): string[] {
  return state.grid.map((row) => row.map((c) => (c ? '#' : '.')).join(''));
}

